const helpers=this.helpers;
const KEY='<REDACTED_SUPABASE_JWT>';
const BASE='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
const BATCH=100;
const MAXTEXT=600;  // truncate post text sent to the LLM (stay under the 30k TPM cap)
const batch=await helpers.httpRequest({method:'GET',url:BASE+'/linkedin_raw?select=activity_id,raw,source,search_input,owner_company&status=eq.pending&order=scraped_at&limit='+BATCH,headers:H,json:true});
const rows=Array.isArray(batch)?batch:[];
if(!rows.length) return [];  // empty queue -> 0 items -> LLM + write nodes skip (no wasted OpenAI call on idle drains)
const cfgRows=await helpers.httpRequest({method:'GET',url:BASE+'/sov_config?select=config&id=eq.1',headers:H,json:true});
const config=(cfgRows&&cfgRows[0]&&cfgRows[0].config)||{};
const comps=await helpers.httpRequest({method:'GET',url:BASE+'/competitors?select=name,aliases,domain,linkedin_urn,type,active,definition,collision_terms&active=eq.true',headers:H,json:true});
const companies=(comps||[]).filter(c=>c.active!==false).map(c=>({name:c.name,aliases:Array.isArray(c.aliases)?c.aliases:[],domain:c.domain||null,linkedin_urn:c.linkedin_urn||null,type:c.type||'direct',definition:c.definition||'',collision_terms:Array.isArray(c.collision_terms)?c.collision_terms:[]}));
const companyEnum=companies.map(c=>c.name).join(', ');
const companyDefs=companies.map(c=>{const dom=c.domain?(' ('+c.domain+')'):'';const nots=(c.collision_terms&&c.collision_terms.length)?('. NOT: '+c.collision_terms.join('; ')):'';return c.name+dom+' \u2014 '+(c.definition||'(no definition yet)')+nots;}).join('\n\n');
// LLM-SKIP: which of this batch are ALREADY attributed in linkedin_posts? Reuse their cached
// companyName/sentiment downstream (no LLM call); engagement + post_weight still get refreshed.
// Kills re-attribution churn on re-scraped posts while keeping engagement current.
const idList=rows.map(r=>'"'+String(r.activity_id)+'"').join(',');
let known={};
try{ const existing=await helpers.httpRequest({method:'GET',url:BASE+'/linkedin_posts?select=activity_id,companyName,sentiment&activity_id=in.('+idList+')',headers:H,json:true}); for(const e of (existing||[])){ if(e&&e.activity_id!=null) known[String(e.activity_id)]={companyName:e.companyName,sentiment:e.sentiment}; } }catch(e){ known={}; }
const keywordPosts=rows.filter(r=>r.source!=='company_page' && !known[String(r.activity_id)]).map(r=>({activity_id:r.activity_id,text:String((r.raw&&r.raw.text)||'').slice(0,MAXTEXT),title:String((r.raw&&r.raw.title)||'').slice(0,200),post_url:(r.raw&&r.raw.post_url)||''}));
return [{json:{config,companyEnum,companyDefs,companies,keywordPosts,batch:rows,batchCount:rows.length,known}}];

const helpers=this.helpers;
const SRK='<REDACTED_SUPABASE_JWT>';
const SB='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H={apikey:SRK,Authorization:'Bearer '+SRK};
function llmText(j){
  if(j&&Array.isArray(j.choices)&&j.choices[0]){const ch=j.choices[0]; if(ch.message&&(ch.message.content||ch.message.reasoning)) return ch.message.content||ch.message.reasoning; if(typeof ch.text==='string') return ch.text;}
  if(j&&typeof j.text==='string') return j.text;
  if(j&&j.message&&typeof j.message.content==='string') return j.message.content;
  return '';
}
const llmMap={};
for(const item of $input.all()){
  let raw=String(llmText(item.json)||'').replace(/```json/gi,'').replace(/```/g,'').trim();
  if(!raw) continue;
  const a=raw.indexOf('['),b=raw.lastIndexOf(']');
  const txt=(a!==-1&&b!==-1&&b>a)?raw.slice(a,b+1):raw;
  let parsed; try{parsed=JSON.parse(txt);}catch(e){continue;}
  const arr=Array.isArray(parsed)?parsed:[parsed];
  for(const e of arr){ if(e&&e.activity_id!=null) llmMap[String(e.activity_id)]=e; }
}
const prep=$('Fetch + Prep Batch').first().json;
const batch=prep.batch||[]; const cfg=prep.config||{}; const companies=prep.companies||[]; const known=prep.known||{};
if(!batch.length) return [{json:{processed:0,written:0,note:'no pending rows'}}];
const nameSet=new Set(companies.map(c=>c.name));
  const directSet=new Set(companies.filter(c=>(c.type||'direct')!=='indirect').map(c=>c.name));
const urnSet=new Set(companies.map(c=>String(c.linkedin_urn||'')).filter(Boolean));
const EMP={};
try{const aff=await helpers.httpRequest({method:'GET',url:SB+'/author_affiliation?select=profile_id,competitor&verdict=eq.employee',headers:H,json:true}); for(const a of (aff||[])){ if(a&&a.profile_id&&a.competitor) EMP[String(a.competitor).trim().toLowerCase()+'|'+String(a.profile_id)]=true; }}catch(e){}
const ew=(cfg.engagementWeights&&cfg.engagementWeights.LinkedIn)||{reaction:1,comment:3,reshare:10,image:1.5};
const clamp=cfg.sentimentClamp||{min:0.5,max:1.3};
const halfLife=(cfg.halfLifeDays&&cfg.halfLifeDays.LinkedIn)||14;
const AB=cfg.authorBaseline||{company:1.0,employee:2.0,external:5.0};
const AEM=cfg.authorEngMult||{company:1.0,employee:1.2,external:2.0};
function computePW(post,companyName,sentiment){
  const reactions=Number(post.totalReactions||0),comments=Number(post.comments||0),reshares=Number(post.reshares||0);
  const hasImage=post.imageURL&&String(post.imageURL).length>0;
  let eng=((ew.reaction!=null?ew.reaction:1)*reactions)+((ew.comment!=null?ew.comment:3)*comments)+((ew.reshare!=null?ew.reshare:10)*reshares);
  if(hasImage) eng+=(ew.image!=null?ew.image:1.5);
  const hasVideo=post&&post.content&&post.content.type==='video';
  if(hasVideo) eng+=(ew.video!=null?ew.video:2);
  const reach=Math.pow(Math.max(0,eng),49/50);
  const sentMult=(post.source==='company_page'||sentiment==null)?1.0:(clamp.min+((Math.max(-3,Math.min(3,Number(sentiment)))+3)/6)*(clamp.max-clamp.min));
  const author=post.author||{}; const headline=String(author.headline||'').toLowerCase(); const authorUrn=String(author.profile_id||''); const cn=String(companyName||'');
  let at;
  if(post.source==='company_page') at='company';
  else if(authorUrn&&urnSet.has(authorUrn)) at='company';
  else if(authorUrn&&cn&&cn!=='NONE'&&EMP[cn.toLowerCase()+'|'+authorUrn]) at='employee';
  else if(cn&&cn!=='NONE'&&headline.indexOf(cn.toLowerCase())!==-1) at='employee';
  else at='external';
  const B=(at==='company')?(AB.company!=null?AB.company:1.0):(at==='employee')?(AB.employee!=null?AB.employee:2.0):(AB.external!=null?AB.external:5.0);
  const M=(at==='company')?(AEM.company!=null?AEM.company:1.0):(at==='employee')?(AEM.employee!=null?AEM.employee:1.2):(AEM.external!=null?AEM.external:2.0);
  let ageDays=0; if(post.posted_at){const d=new Date(post.posted_at); if(!isNaN(d)) ageDays=Math.max(0,(Date.now()-d.getTime())/86400000);}
  const timeDecay=ageDays<=7?1:Math.pow(2,-ageDays/halfLife);
  return parseFloat(((B+reach*M)*sentMult*timeDecay).toFixed(6));
}
const upserts=[]; const doneIds=[];
for(const row of batch){
  const post=row.raw||{}; const aid=String(row.activity_id); doneIds.push(aid);
  let companyName,sentiment,reasoning; let companiesArr=null;
  if(row.source==='company_page'){ companyName=row.owner_company||'NONE'; sentiment=null; reasoning='company self-post (auto-accepted)'; }
  else if(known[aid]){ companyName=known[aid].companyName||'NONE'; sentiment=(known[aid].sentiment!=null)?known[aid].sentiment:null; reasoning='engagement refresh (cached attribution)'; }
  else { const e=llmMap[aid]; companyName=(e&&e.companyName)?e.companyName:'NONE'; sentiment=(e&&e.sentiment!=null)?e.sentiment:null; reasoning=(e&&e.reasoning)?e.reasoning:'no match'; companiesArr=(e&&Array.isArray(e.companies))?e.companies:null; }
  // HARD RULE: a post scraped from a company's own LinkedIn page (owner_company set) is ALWAYS
  // attributed to that company - never left to the LLM (which could drop it to NONE).
  const ownerCo=(row.owner_company==null)?'':String(row.owner_company).trim();
  if(ownerCo && ownerCo.toLowerCase()!=='none'){ companyName=ownerCo; reasoning='[auto: own company-page post] '+String(reasoning||''); }
  const _src=(companiesArr&&companiesArr.length)?companiesArr:((companyName&&companyName!=='NONE')?[{companyName,sentiment,reasoning}]:[]);
  const company_names=_src.filter(c=>c&&c.companyName&&c.companyName!=='NONE').map(c=>({name:c.companyName,sentiment:(c.sentiment!=null?c.sentiment:null),reasoning:c.reasoning||''})).filter(c=>directSet.has(c.name)||(row.source==='company_page'&&c.name===ownerCo));
  if(company_names.length){ companyName=company_names[0].name; sentiment=company_names[0].sentiment; reasoning=company_names[0].reasoning||reasoning; }
  const isReal=companyName&&companyName!=='NONE'&&nameSet.has(companyName);
  const hasVideo=post&&post.content&&post.content.type==='video';
  const pw=isReal?computePW(post,companyName,sentiment):null;
  upserts.push({activity_id:aid,companyName:companyName,author:post.author||{},text:post.text||'',title:post.title||'',totalReactions:Number(post.totalReactions||0),comments:Number(post.comments||0),reshares:Number(post.reshares||0),imageURL:post.imageURL||'',posted_at:post.posted_at||null,sentiment:sentiment,reasoning:reasoning,search_input:row.search_input||null,post_weight:pw,company_names:company_names,has_video:!!hasVideo});
}
let written=0;
if(upserts.length){ try{ await helpers.httpRequest({method:'POST',url:SB+'/linkedin_posts?on_conflict=activity_id',headers:Object.assign({},H,{'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=minimal'}),body:upserts,json:true}); written=upserts.length; }catch(e){ return [{json:{error:'upsert failed: '+(e&&e.message||e)}}]; } }
if(doneIds.length){ try{ await helpers.httpRequest({method:'PATCH',url:SB+'/linkedin_raw?activity_id=in.('+doneIds.map(x=>'"'+x+'"').join(',')+')',headers:Object.assign({},H,{'Content-Type':'application/json','Prefer':'return=minimal'}),body:{status:'done'},json:true}); }catch(e){} }
const attributed=upserts.filter(u=>u.post_weight!=null).length;
const refreshed=Object.keys(known).length;
return [{json:{processed:batch.length,written:written,attributed:attributed,none:written-attributed,llmSkipped:refreshed}}];
